import{_ as e}from"./chunks/00-sidebar-overview.Cutxsm52.js";import{_ as r,o,c as a,a2 as n}from"./chunks/framework.D4up2k3b.js";const b=JSON.parse('{"title":"什么是 filebox","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":null}'),s={name:"guide/introduction.md"};function i(d,t,l,g,c,h){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="什么是-filebox" tabindex="-1">什么是 filebox <a class="header-anchor" href="#什么是-filebox" aria-label="Permalink to &quot;什么是 filebox&quot;">​</a></h1><p>filebox 是面向实验室 / HPC / 自建服务器的<strong>只读远程文件浏览器</strong>：在每台机器上装一个小 Agent，在你控制的机器上跑一个 Hub，用浏览器打开一个 HTTPS 页面，就能浏览文件、预览图表与数据集、搜索工作区、查看系统负载。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>浏览器 ──HTTPS──▶ Hub ◀──WSS（出站）── Agent ──▶ 本地文件</span></span></code></pre></div><p><img src="'+e+'" alt="filebox 界面总览"></p><ul><li><strong>浏览器</strong>：只访问 Hub，不直连 Agent。</li><li><strong>Hub</strong>：认证用户、托管前端、把请求路由到对应机器。</li><li><strong>Agent</strong>：装在目标机上，<strong>主动出站</strong>连到 Hub。目标机不需要公网 IP、入站端口、VPN 或端口映射。断线后会自动重连，身份不变、侧栏不产生重复条目。</li></ul><h2 id="适合谁" tabindex="-1">适合谁 <a class="header-anchor" href="#适合谁" aria-label="Permalink to &quot;适合谁&quot;">​</a></h2><p>研究者、分析师、数据科学家：结果以文件形式散落在共享服务器上，需要随时用手机或笔记本<strong>看一眼图、表、日志</strong>，而不想为了瞄一眼就 <code>scp</code> 一整份大文件。</p><p>filebox 不是网盘同步工具，也不是完整的远程桌面——它是「结果文件的前门」：打开、预览、搜索、偶尔传一个小临时文件或开一扇受 TOTP 保护的终端。</p><h2 id="能做什么-v2-1-0" tabindex="-1">能做什么（v2.1.0） <a class="header-anchor" href="#能做什么-v2-1-0" aria-label="Permalink to &quot;能做什么（v2.1.0）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>说明</th></tr></thead><tbody><tr><td><strong>Files</strong></td><td>大目录流畅列表、面包屑、过滤、钉选、多标签预览</td></tr><tr><td><strong>Explorer</strong></td><td>树形展开式浏览，与 Files 共享当前位置</td></tr><tr><td><strong>Search</strong></td><td>文件名或内容正则；可限范围、扩展名、忽略目录</td></tr><tr><td><strong>Collections</strong></td><td>跨目录的虚拟文件合集，不复制、不移动</td></tr><tr><td><strong>Transfer</strong></td><td>唯一可写的临时上传目录（配额、禁覆盖）</td></tr><tr><td><strong>Terminal</strong></td><td>可选；Agent 本地 TOTP 守护的交互式 shell（<strong>非沙箱</strong>）</td></tr><tr><td><strong>Stats</strong></td><td>CPU / 内存 / 负载 / 按用户占用 / 进程表</td></tr><tr><td><strong>Audit / Health</strong></td><td>登录审计与 Hub / Agent 健康</td></tr></tbody></table><h2 id="默认安全边界" tabindex="-1">默认安全边界 <a class="header-anchor" href="#默认安全边界" aria-label="Permalink to &quot;默认安全边界&quot;">​</a></h2><ul><li>浏览协议<strong>只读</strong>：不能改、删、重命名远端文件。</li><li>敏感路径（<code>.ssh/</code>、<code>.env*</code>、<code>*.pem</code> 等）默认拒绝，即使在允许的根目录内。</li><li>浏览严格限制在已添加的 root 内；<code>..</code>、符号链接逃逸等会被挡住。</li><li>两个显式例外（需能力开启 / 本地配置）： <ul><li><strong>Transfer</strong>：仅写入 Agent 专用临时目录。</li><li><strong>Terminal</strong>：Agent 本地 TOTP 守护的交互式 shell（<strong>非沙箱</strong>，能做 OS 用户能做的一切）。</li></ul></li></ul><p>详见 <a href="/filebox/docs/features/security">安全与敏感文件</a>。</p><h2 id="和在线演示的关系" tabindex="-1">和在线演示的关系 <a class="header-anchor" href="#和在线演示的关系" aria-label="Permalink to &quot;和在线演示的关系&quot;">​</a></h2><p><a href="https://zhimingye.github.io/filebox/" target="_blank" rel="noreferrer">在线演示</a> 是静态 mock UI，交互布局与真实 Hub 前端一致，适合先熟悉侧栏与视图。本文档截图主要来自该演示，并标注与真实应用的差异（例如 Search 在真实应用中是浮窗，而不是替换主视图；Explorer / Settings / Login / Audit 以真实前端为准）。</p><p>下一篇：<a href="./quick-start">快速开始</a></p>',16)])])}const f=r(s,[["render",i]]);export{b as __pageData,f as default};
